contract InvMutTest {
    C c;
    address constant FIXED_DEST = address(0xABCD);
    constructor(C _c) { c = _c; }
    fallback() external payable {
        // Respond to the factory-side view call protocolFeeDestination() made by c.initialize()
        if (msg.sig == 0x2b7a409c) {
            assembly {
                mstore(0x00, FIXED_DEST)
                return(0x00, 0x20)
            }
        }
        assembly {
            return(0x00, 0x00)
        }
    }
    function run(uint256 credChainId_, uint256 credId_, string calldata verificationType_) public {
        c.initialize(credChainId_, credId_, verificationType_, FIXED_DEST);
        assert(c.credChainId() == credChainId_ && c.credId() == credId_ && c.tokenIdCounter() == 1);
    }
    receive() external payable {}
}

