contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 chainId, uint256 cred, string memory vType, address feeDest) public {
        require(feeDest != address(0));
        c.initialize(chainId, cred, vType, feeDest);
        require(!c.paused());
        c.pause();
        bool p1 = c.paused();
        bool reverted;
        address[] memory none;
        try c.claimFromFactory(1, address(this), address(this), address(this), 1, bytes32(0), "uri") { reverted = false; }
        catch { reverted = true; }
        c.unPause();
        bool p2 = c.paused();
        assert(p1 && !p2 && reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    uint256 artFeeVal = 100;

    constructor(C _c) { c = _c; }

    fallback() external payable {
        if (msg.sig == bytes4(keccak256("artCreateFee()"))) {
            bytes memory ret = abi.encode(artFeeVal);
            assembly { return(add(ret, 0x20), 0x20) }
        }
        if (msg.sig == bytes4(keccak256("protocolFeeDestination()"))) {
            bytes memory ret2 = abi.encode(address(this));
            assembly { return(add(ret2, 0x20), 0x20) }
        }
    }

    function run(uint256 artId, uint256 extra) public {
        require(artId > 0);
        require(extra > 0 && extra < 1 ether);
        c.initialize(1, 1, "v", address(this));
        uint256 t0 = c.tokenIdCounter();
        uint256 t = c.createArtFromFactory{value: artFeeVal + extra}(artId);
        assert(t == t0 && c.getTokenIdFromFactoryArtId(artId) == t0 && c.tokenIdCounter() == t0 + 1);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Answers the factory-view callbacks made by c during initialize():
    // protocolFeeDestination() -> address(this).
    fallback() external payable {
        assembly {
            mstore(0, address())
            return(0, 0x20)
        }
    }

    function run(uint256 artId, uint256 quantity, bytes32 data) public {
        c.initialize(1, 1, "v", address(this));

        // On a fresh contract no artId is registered yet.
        uint256 mappedTokenId = c.getTokenIdFromFactoryArtId(artId);
        require(mappedTokenId == 0);

        bool reverted;
        try c.claimFromFactory(artId, address(0xBEEF), address(0xC0DE), address(0xFACE), quantity, data, "uri") {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.getTokenIdFromFactoryArtId(artId) == 0);
    }

    receive() external payable {}
}

