contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(!c.paused());
        c.pause();
        bool p1 = c.paused();
        bool reverted;
        try c.pause() { reverted = false; } catch { reverted = true; }
        bool p2 = c.paused();
        c.unPause();
        bool p3 = c.paused();
        assert(p1 && p2 && reverted && !p3);
    }
    receive() external payable {}
}

