contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address op, address other) public payable {
        require(op != address(0));
        require(other != address(0));
        require(op != other);
        require(op != address(this));
        require(other != address(this));
        c.setApprovalForAll(op, true);
        assert(c.isApprovedForAll(address(this), op) && !c.isApprovedForAll(address(this), other));
    }
    receive() external payable {}
}

